        miniChefSaladStep4: "Taste it and decorate however you like!",
        miniChefSaladWhy: "Noticed how a cut apple turns brown? That happens because air touches the fruit and it reacts with oxygen — like very slow rusting! A little orange juice helps stop that.",
        miniChefRecipeSandwichTitle: "Fun Sandwich",
        miniChefSandwichStep1: "Pick two slices of bread",
        miniChefSandwichStep2: "Spread the butter on the bread",
        miniChefSandwichStep3: "Add the cheese and ham",
        miniChefSandwichStep4: "Close the sandwich with the other slice!",
        miniChefSandwichWhy: "Noticed how butter goes soft when you touch it? The warmth from your hands or warm bread melts the fat in the butter — that's why it's solid in the fridge and soft at room temperature.",
