        circuitBulbTitle: "Light the Bulb",
        circuitBulbWhy: "Electricity only flows when the circuit is closed — a complete path with no gaps: from the battery, through the wire, to the bulb, and back. That closed loop is what makes the bulb light up!",
        circuitMotorTitle: "Start the Motor",
        circuitMotorWhy: "A motor has a coil of wire inside. When electricity flows through it in a closed circuit, it creates a magnetic force that makes the motor spin — that's how fans and electric toy cars work!",
        circuitBuzzerTitle: "Ring the Buzzer",
        circuitBuzzerWhy: "When you close the switch, the circuit is complete and electricity reaches the buzzer, making it vibrate very fast — that vibration is what makes the sound!",
