        circuitTitle: "Schaltkreis-Labor",
        circuitHelp: "Wähle eine Herausforderung und tippe die Teile in der richtigen Reihenfolge an, um den Stromkreis zu schließen. Ist der Kreis vollständig, leuchtet die Lampe, dreht sich der Motor oder klingelt die Klingel!",
        circuitIntro: "Lass uns Batterien, Kabel und andere Teile verbinden, um tolle Dinge zu bewirken! Tippe die Teile in der richtigen Reihenfolge an, um den Stromkreis zu schließen.",
