        circuitBulbTitle: "Lampe Einschalten",
        circuitBulbWhy: "Strom fließt nur, wenn der Stromkreis geschlossen ist — ein vollständiger Weg ohne Lücken: von der Batterie, durch das Kabel, zur Lampe und zurück. Dieser geschlossene Kreis lässt die Lampe leuchten!",
        circuitMotorTitle: "Motor Starten",
        circuitMotorWhy: "Ein Motor hat eine Drahtspule im Inneren. Fließt Strom in einem geschlossenen Kreis hindurch, entsteht eine magnetische Kraft, die den Motor drehen lässt — so funktionieren Ventilatoren und elektrische Spielzeugautos!",
        circuitBuzzerTitle: "Klingel Läuten",
