        circuitTrafficTitle: "Ampel",
        circuitTrafficWhy: "Jede Ampellampe ist ihr eigener kleiner Stromkreis. Sie leuchten der Reihe nach rot, gelb, dann grün, um Autos und Menschen zu sagen, wann sie anhalten und wann sie sicher weitergehen können.",
